                        quote = 0;
                    }
                    base = base.wrapping_add(1);
                    continue;
                } else if b0 == '"' as c_int || b0 == '\'' as c_int {
                    quote = b0;
                    base = base.wrapping_add(1);
                    continue;
                }
            }

            if b0 == first_i {
                if check_third {
                    // SAFETY: `base < len` and `len` was reduced by 2 when `third != 0`,
